// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Per-browser sync state (IndexedDB): the last-synchronised encrypted database
// (the merge base) and encrypted conflict backups, keyed per database. This
// state never leaves the browser and is deliberately NOT stored in the user's
// Nextcloud files.

const DB_NAME = 'upm-sync';
const STORE = 'blobs';
const VERSION = 1;
const LEGACY_BASE_KEY = 'base';
const CONFLICT_PREFIX = 'conflict-';
const MAX_CONFLICT_BACKUPS = 10;
/** Disambiguates backups created within the same millisecond. */
let conflictSequence = 0;

interface BlobRecord {
  key: string;
  bytes: Uint8Array;
  timestamp: number;
}

/** Key of the merge base for one database. */
export function baseKey(databaseId: string): string {
  return `${databaseId}:base`;
}

/** Open (creating if needed) the sync IndexedDB database. */
function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: 'key' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB open failed'));
  });
}

/** Read a stored blob by key, or null when it does not exist. */
async function readBlob(key: string): Promise<Uint8Array | null> {
  const db = await openDatabase();
  try {
    const record = await new Promise<BlobRecord | undefined>((resolve, reject) => {
      const request = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);
      request.onsuccess = () => resolve(request.result as BlobRecord | undefined);
      request.onerror = () => reject(request.error);
    });
    return record ? new Uint8Array(record.bytes) : null;
  } finally {
    db.close();
  }
}

/** Store a blob (a copy of the bytes) under `key`. */
async function writeBlob(key: string, bytes: Uint8Array): Promise<void> {
  const db = await openDatabase();
  try {
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      const record: BlobRecord = { key, bytes: new Uint8Array(bytes), timestamp: Date.now() };
      tx.objectStore(STORE).put(record);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } finally {
    db.close();
  }
}

/** Delete a blob by key. */
async function deleteBlob(key: string): Promise<void> {
  const db = await openDatabase();
  try {
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).delete(key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } finally {
    db.close();
  }
}

/** All stored keys (used to prune old conflict backups). */
async function listKeys(): Promise<string[]> {
  const db = await openDatabase();
  try {
    return await new Promise<string[]>((resolve, reject) => {
      const request = db.transaction(STORE, 'readonly').objectStore(STORE).getAllKeys();
      request.onsuccess = () => resolve((request.result as IDBValidKey[]).map(String));
      request.onerror = () => reject(request.error);
    });
  } finally {
    db.close();
  }
}

/** The last-synchronised encrypted database for `databaseId`, or null. */
export function getBase(databaseId: string): Promise<Uint8Array | null> {
  return readBlob(baseKey(databaseId));
}

/** Record the encrypted database that both sides now agree on. */
export async function saveBase(databaseId: string, bytes: Uint8Array): Promise<void> {
  await writeBlob(baseKey(databaseId), bytes);
}

/** Forget the base (e.g. after a master-password change). */
export async function clearBase(databaseId: string): Promise<void> {
  await deleteBlob(baseKey(databaseId));
}

/** True when a single-database base from before Phase 9 is still stored. */
export async function hasLegacyBase(): Promise<boolean> {
  return (await readBlob(LEGACY_BASE_KEY)) !== null;
}

/**
 * Move the pre-Phase-9 `base` record to the given database id. Only call this
 * when it is unambiguous which database the legacy base belongs to.
 */
export async function migrateLegacyBase(databaseId: string): Promise<boolean> {
  const legacy = await readBlob(LEGACY_BASE_KEY);
  if (legacy === null) {
    return false;
  }
  await writeBlob(baseKey(databaseId), legacy);
  await deleteBlob(LEGACY_BASE_KEY);
  return true;
}

/** Store an encrypted conflict backup; returns the key it was stored under. */
export async function saveConflictBackup(
  databaseId: string,
  bytes: Uint8Array,
): Promise<string> {
  conflictSequence += 1;
  const sequence = String(conflictSequence).padStart(6, '0');
  const key = `${databaseId}:${CONFLICT_PREFIX}${new Date().toISOString()}-${sequence}`;
  await writeBlob(key, bytes);
  await pruneConflictBackups(databaseId);
  return key;
}

/** Read a conflict backup by key, or null when it does not exist. */
export function getConflictBackup(key: string): Promise<Uint8Array | null> {
  return readBlob(key);
}

/** Keep only the newest {@link MAX_CONFLICT_BACKUPS} backups of a database. */
export async function pruneConflictBackups(
  databaseId: string,
  keep = MAX_CONFLICT_BACKUPS,
): Promise<void> {
  const prefix = `${databaseId}:${CONFLICT_PREFIX}`;
  const keys = (await listKeys()).filter((key) => key.startsWith(prefix)).sort();
  for (const key of keys.slice(0, Math.max(0, keys.length - keep))) {
    await deleteBlob(key);
  }
}
